WITH ch AS (SELECT json_extract_string(state,'$.asset') AS a, SUM(CAST(json_extract(state,'$.amount') AS BIGINT)) AS charged, MAX(json_extract_string(state,'$.period')) AS last_period FROM objects WHERE object_type = 'depreciation_charge' GROUP BY 1) SELECT COALESCE(json_extract_string(f.state,'$.number'), '') AS number, json_extract_string(f.state,'$.name') AS name, CAST(json_extract(f.state,'$.initial_value') AS BIGINT) AS initial_value, COALESCE(ch.charged, 0) AS charged, CAST(json_extract(f.state,'$.initial_value') AS BIGINT) - COALESCE(ch.charged, 0) AS net, COALESCE(ch.last_period, '') AS last_period, json_extract_string(f.state,'$.status') AS status, f.object_id AS _of FROM objects f LEFT JOIN ch ON ch.a = f.object_id WHERE f.object_type = 'fixed_asset' ORDER BY json_extract_string(f.state,'$.status'), json_extract_string(f.state,'$.accepted_date'), f.object_id
